// Bottle presentation shared by the Cellar page and the Collection's Cellar
// section: tier styling, the real catalog (src/lib/wine-catalog.json, keyed by
// skuId = tokenId >> 16, generated by gacha-contract/script/catalog.py) and the
// mock catalog used when NEXT_PUBLIC_WINE_GACHA_ADDRESS is unset.

import { wineConfigured, type WineShelf } from "@/lib/wine"
import catalog from "@/lib/wine-catalog.json"

