export const MOCK_COLLECTION = "0x000000000000000000000000000000000000cafe" as const
/** One pull, 6dp — the mainnet price (tokenAt(0) on 999). The stage always reads the
 *  live price off the shelf; this is the mock shelf's price and the fallback the tier
 *  bands scale against where no shelf is loaded (the collection panel). Testnet still
 *  charges $100 — its bands stretch accordingly once its shelf is read. */
export const WINE_PULL_UNITS6 = BigInt(80_000_000)
export const MOCK_PRICE_UNITS6 = WINE_PULL_UNITS6

// Preview-only buyback quote (6dp) — an id formula, so the mock shelf grades
// across every tier. Real bottles grade off the live sellbackQuote.
export const mockQuote = (id: bigint) => {
  const n = Number(id)
  return BigInt(n % 12 === 0 ? 1_400_000_000 : n % 4 === 0 ? 320_000_000 : n % 3 === 0 ? 160_000_000 : 60_000_000)
}

export function mockShelf(): WineShelf {
  return {
    prizeCount: 12,
    stockEpoch: 1,
    tokens: [{ id: 0, address: MOCK_COLLECTION, symbol: "USDC", priceUnits6: MOCK_PRICE_UNITS6 }],
    prizes: MOCK_NAMES.map((_, i) => ({ collection: MOCK_COLLECTION, tokenId: BigInt(i) })),
  }
}

// tokenId = skuId << 16 | serial (PrizeNFT.encode). The catalog is per WINE; the serial is
// the bottle number within it. An id off the catalog (a sku stocked after this build) still
// gets a name, just not a pretty one — same for art, where null means "no label scan".
const WINES = catalog as Record<string, { name: string; image: string } | undefined>
const skuOf = (tokenId: string | bigint) => (BigInt(tokenId) >> BigInt(16)).toString()
const serialOf = (tokenId: string | bigint) => Number(BigInt(tokenId) & BigInt(0xffff))

export const bottleName = (p: { collection: string; tokenId: string | bigint }) => {
  if (!wineConfigured()) return MOCK_NAMES[Number(p.tokenId) % MOCK_NAMES.length]
  const w = WINES[skuOf(p.tokenId)]
  return w ? `${w.name} #${serialOf(p.tokenId)}` : `Bottle #${p.tokenId}`
}

// Same file the tokenURI metadata points at: /prize/<sku>.webp under public/.
export const bottleImg = (p: { tokenId: string | bigint }) => {
  if (!wineConfigured()) return MOCK_IMGS[Number(p.tokenId) % MOCK_IMGS.length]
  const w = WINES[skuOf(p.tokenId)]
  return w ? `/prize/${w.image}` : null
}

/**
 * A bottle's tier from what the house will actually pay for it.
 *
 * Derived from the live sellback quote, not invented: `mockTier` is an id % 12 formula that
 * exists only for the pre-deploy preview, and stamping it on real bottles would dress
 * fabricated rarity as fact on a page whose whole claim is that the draw is provable. The
 * quote is on-chain, write-once and the number the winner is paid, so it is the honest signal.
 *
 * Bands follow the operations sheet's own vocabulary — Grand Prize / Icon / Cellar / Entry —
 * as MULTIPLES of the pull price, so a bottle worth 14 pulls reads differently from one
 * worth a third whatever a pull costs. Fixed dollar cut-offs drifted off the sheet the
 * moment the price moved from $100 to $80; `x10` is the multiple in tenths (25 = 2.5×).
 */
export const WINE_TIERS = [
  { x10: 100, tier: 5, label: "Grand Prize", glow: "var(--brand)" },
  { x10: 25, tier: 4, label: "Icon", glow: "#c084fc" },
  { x10: 15, tier: 3, label: "Reserve", glow: "#60a5fa" },
  { x10: 8, tier: 2, label: "Cellar", glow: "#34d399" },
  { x10: 0, tier: 1, label: "Entry", glow: "var(--muted-foreground)" },
] as const

/** The house buys a bottle back at 90% of what it's worth. The quote is the number
 *  on-chain; the value a winner sees is the quote grossed back up — so the bottle's
 *  headline reads like a slab's insured value, and the sell button reads the offer. */
export const WINE_BUYBACK_RATIO = 0.9

export function wineTier(quoteUnits6: bigint | undefined, pullUnits6: bigint = WINE_PULL_UNITS6) {
  const q = (quoteUnits6 ?? BigInt(0)) * BigInt(10)
  return WINE_TIERS.find((t) => q >= pullUnits6 * BigInt(t.x10)) ?? WINE_TIERS[WINE_TIERS.length - 1]
}
